import React from "react";
import Slider from "react-slick"; // Import react-slick
import "slick-carousel/slick/slick.css"; // Slick carousel styles
import "slick-carousel/slick/slick-theme.css"; // Optional theme styles

function EventsSlider() {
  const settings = {
    dots: true, // Enable pagination dots
    arrows: true, // Enable navigation arrows
    infinite: true, // Enable continuous looping
    autoplay: true, // Enable autoplay
    autoplaySpeed: 2000, // Autoplay speed in milliseconds
    slidesToShow: 1, // Number of slides visible at a time
    slidesToScroll: 1, // Number of slides to scroll per swipe
  };

  return (
    <div style={styles.wrapper}>
      {/* Üst Çizgiler ve Noktalar */}
      <div style={styles.topBar}>
        <div style={styles.dots}></div>
        <div style={styles.line}></div>
      </div>

      {/* Ana İçerik */}
      <div style={styles.content}>
        {/* Sol Kesik Çizgi */}
        <div style={styles.sideLineLeft}></div>

        {/* İçerik Kutusu (Görseller Burada) */}
        <div style={styles.contentBox}>
          {/* Slick Slider */}
          <Slider {...settings}>
            <div>
              <img
                src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
                alt="Slide 1"
                style={styles.image}
              />
            </div>
            <div>
              <img
                src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
                alt="Slide 2"
                style={styles.image}
              />
            </div>
            {/* Add more slides here */}
          </Slider>
        </div>

        {/* Sağ Kesik Çizgi */}
        <div style={styles.sideLineRight}></div>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "1024px",
    marginTop: "50px",
    marginLeft: "auto",
    marginRight: "auto",
    backgroundColor: "rgb(246, 248, 255)",
  },

  content: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    marginTop: "20px",
    height: "400px",
    marginBottom: "0",
  },

  contentBox: {
    width: "987px", // Temporarily comment out or reduce the width
    height: "400px", // Temporarily comment out or reduce the height
    backgroundColor: "#293349", // Optional
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    padding: "10px",
    overflow: "hidden",
    margin: "0 auto",
  },

  image: {
    width: "100%",
    height: "auto",
    objectFit: "cover",
    borderRadius: "5px",
  },

  bottomBar: {
    width: "100%",
    height: "100px",
    backgroundColor: "#293349",
    marginTop: "20px",
  },
};

export default EventsSlider;
